data.customPricingJs:
(() => {
  const root = document.querySelector(".fare-box");
  if (!root) return;

  const tabs = root.querySelectorAll(".fare-tab");
  const columns = root.querySelectorAll("[data-fare]");

  tabs.forEach((tab) => {
    tab.addEventListener("click", () => {
      const selected = tab.getAttribute("data-select");

      tabs.forEach((item) => {
        item.setAttribute(
          "aria-pressed",
          String(item.getAttribute("data-select") === selected)
        );
      });

      columns.forEach((cell) => {
        cell.classList.toggle(
          "is-active",
          cell.getAttribute("data-fare") === selected
        );
      });
    });
  });
})();
